using System.Net;
using Microsoft.AspNetCore.Mvc.Testing;

namespace PlainApi.Evals.Tests;

[TestClass]
public class ApiEndpointEvals
{
    private static WebApplicationFactory<Program> _factory = null!;
    private static HttpClient _client = null!;

    [ClassInitialize]
    public static void Init(TestContext _)
    {
        _factory = new WebApplicationFactory<Program>();
        _client = _factory.CreateClient();
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        _client.Dispose();
        _factory.Dispose();
    }

    [TestMethod]
    public async Task RootEndpoint_ReturnsSuccess()
    {
        var response = await _client.GetAsync("/");

        Assert.AreEqual(HttpStatusCode.OK, response.StatusCode);
        var content = await response.Content.ReadAsStringAsync();
        Assert.AreEqual("Hello, World!", content);
    }

    [TestMethod]
    public async Task HealthEndpoint_ReturnsHealthy()
    {
        var response = await _client.GetAsync("/health");

        Assert.AreEqual(HttpStatusCode.OK, response.StatusCode);
        var content = await response.Content.ReadAsStringAsync();
        Assert.IsTrue(content.Contains("healthy"));
    }

    [TestMethod]
    public async Task NonExistentEndpoint_Returns404()
    {
        var response = await _client.GetAsync("/nonexistent");

        Assert.AreEqual(HttpStatusCode.NotFound, response.StatusCode);
    }

    [TestMethod]
    public async Task RootEndpoint_ResponseTime_IsAcceptable()
    {
        // Warm up
        await _client.GetAsync("/");

        var sw = System.Diagnostics.Stopwatch.StartNew();
        await _client.GetAsync("/");
        sw.Stop();

        Assert.IsTrue(sw.ElapsedMilliseconds < 1000,
            $"Response took {sw.ElapsedMilliseconds}ms, expected < 1000ms");
    }
}

